-- DBA and operations: session control, transactions, system views, tuning queries
ALTER SESSION SET NLS_DATE_FORMAT = 'YYYY-MM-DD HH24:MI:SS';
ALTER SESSION SET CURRENT_SCHEMA = hr;
ALTER SESSION SET TIME_ZONE = 'UTC';
ALTER SESSION SET NLS_LANGUAGE = 'AMERICAN' NLS_TERRITORY = 'AMERICA';
ALTER SESSION ENABLE PARALLEL DML;
ALTER SYSTEM KILL SESSION '123,4567' IMMEDIATE;
ALTER SYSTEM SET open_cursors = 500 SCOPE = BOTH;
ALTER SYSTEM FLUSH SHARED_POOL;
ALTER USER app_user IDENTIFIED BY "N3wPass#2" ACCOUNT UNLOCK;
ALTER USER app_user QUOTA 500M ON users;
ALTER TABLESPACE users ADD DATAFILE '/u01/oradata/users02.dbf' SIZE 1G AUTOEXTEND ON NEXT 100M MAXSIZE UNLIMITED;
CREATE TABLESPACE app_data DATAFILE '/u01/oradata/app_data01.dbf' SIZE 500M AUTOEXTEND ON;
CREATE PROFILE app_profile LIMIT SESSIONS_PER_USER 10 IDLE_TIME 30;
CREATE DATABASE LINK prod_link CONNECT TO remote_user IDENTIFIED BY "pwd" USING 'PRODDB';
DROP DATABASE LINK prod_link;
DROP USER app_user CASCADE;
DROP ROLE app_role;
DROP TABLESPACE app_data INCLUDING CONTENTS AND DATAFILES;
GRANT EXECUTE ON dbms_stats TO app_user;
GRANT app_role TO app_user;
GRANT SELECT ANY TABLE TO reporting_user;
REVOKE CREATE SESSION FROM app_user;
COMMIT;
COMMIT WORK;
ROLLBACK;
ROLLBACK TO SAVEPOINT sp1;
SAVEPOINT sp1;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
SET TRANSACTION READ ONLY;
LOCK TABLE orders IN EXCLUSIVE MODE NOWAIT;
LOCK TABLE orders IN ROW SHARE MODE;
ANALYZE TABLE orders COMPUTE STATISTICS;
EXPLAIN PLAN FOR SELECT * FROM orders WHERE customer_id = 5;
EXPLAIN PLAN SET STATEMENT_ID = 'q1' FOR SELECT * FROM orders;
SELECT * FROM TABLE(DBMS_XPLAN.DISPLAY);
SELECT * FROM TABLE(DBMS_XPLAN.DISPLAY_CURSOR(NULL, NULL, 'ALLSTATS LAST'));
SELECT s.sid, s.serial#, s.username, s.status, s.machine, s.program, q.sql_text FROM v$session s LEFT JOIN v$sql q ON s.sql_id = q.sql_id WHERE s.type = 'USER' AND s.status = 'ACTIVE';
SELECT l.session_id, o.object_name, l.locked_mode FROM v$locked_object l JOIN dba_objects o ON o.object_id = l.object_id;
SELECT tablespace_name, ROUND(SUM(bytes) / 1048576) AS mb_free FROM dba_free_space GROUP BY tablespace_name;
SELECT df.tablespace_name, df.total_mb, NVL(fs.free_mb, 0) AS free_mb, ROUND((df.total_mb - NVL(fs.free_mb, 0)) / df.total_mb * 100, 1) AS pct_used FROM (SELECT tablespace_name, SUM(bytes) / 1048576 AS total_mb FROM dba_data_files GROUP BY tablespace_name) df LEFT JOIN (SELECT tablespace_name, SUM(bytes) / 1048576 AS free_mb FROM dba_free_space GROUP BY tablespace_name) fs ON df.tablespace_name = fs.tablespace_name ORDER BY pct_used DESC;
SELECT sql_id, executions, elapsed_time / 1000000 AS elapsed_s, buffer_gets, SUBSTR(sql_text, 1, 100) AS txt FROM v$sqlarea WHERE parsing_schema_name = 'APP' ORDER BY elapsed_time DESC FETCH FIRST 25 ROWS ONLY;
SELECT object_name, object_type, status FROM user_objects WHERE status = 'INVALID';
SELECT index_name, uniqueness, status FROM user_indexes WHERE table_name = 'ORDERS';
SELECT * FROM nls_session_parameters WHERE parameter LIKE 'NLS_DATE%';
SELECT banner FROM v$version;
SELECT name, value FROM v$parameter WHERE name IN ('sga_target', 'pga_aggregate_target');
SELECT username, account_status, expiry_date FROM dba_users WHERE expiry_date < SYSDATE + 14;
SELECT grantee, privilege FROM dba_sys_privs WHERE grantee = :u;
SELECT job_name, state, last_start_date FROM dba_scheduler_jobs WHERE enabled = 'TRUE';
SELECT * FROM dba_hist_snapshot WHERE begin_interval_time > SYSTIMESTAMP - INTERVAL '1' DAY;
SELECT inst_id, COUNT(*) FROM gv$session GROUP BY inst_id;
SELECT * FROM all_source WHERE name = 'MY_PKG' AND type = 'PACKAGE BODY' ORDER BY line;
